edits.old:
use_drop(move || {
    let mut guard = guard;
    if let Some(runtime) = runtime
        && let Some(old) = guard.write().take()
    {
        runtime.retire_draft_owner(old);
    }
});

edits.new:
use_drop(move || {
    let mut guard = guard;
    if let Some(_runtime) = runtime
        && let Some(old) = guard.write().take()
    {
        std::mem::forget(old);
    }
});
